import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.helper.Validate;

public class SafelistTest {

    @Test
    public void none_SimpleTextTest() {
        Safelist simple = Safelist.simpleText();
        assertFalse(simple.isSafeTag("img"));
        assertTrue(simple.isSafeTag("p"));
    }

    @Test
    public void basic_SimpleTextTest() {
        Safelist basic = Safelist.basic();
        assertTrue(basic.isSafeTag("img"));
        assertTrue(basic.isSafeTag("p"));
    }

    @Test
    public void basicWithImages_SimpleTextTest() {
        Safelist basicWithImages = Safelist.basicWithImages();
        assertTrue(basicWithImages.isSafeTag("img"));
        assertTrue(basicWithImages.isSafeTag("p"));
    }

    @Test
    public void relaxed_SimpleTextTest() {
        Safelist relaxed = Safelist.relaxed();
        assertTrue(relaxed.isSafeTag("img"));
        assertTrue(relaxed.isSafeTag("p"));
    }

    @Test
    public void none_addTags_SimpleTextTest() {
        Safelist noneAddImg = Safelist.none().addTags("img");
        assertTrue(noneAddImg.isSafeTag("img"));
        assertFalse(noneAddImg.isSafeTag("p"));
    }

    @Test
    public void basic_removeTags_SimpleTextTest() {
        Safelist basicRemoveImg = Safelist.basic().removeTags("img");
        assertFalse(basicRemoveImg.isSafeTag("img"));
        assertTrue(basicRemoveImg.isSafeTag("p"));
    }

    @Test
    public void none_addAttributes_SimpleTextTest() {
        Safelist noneAddImgAttr = Safelist.none().addAttributes("img", "src", "test.jpg");
        assertTrue(noneAddImgAttr.isSafeAttribute("img", null, new Attribute(null, "src", "test.jpg")));
        assertFalse(noneAddImgAttr.isSafeAttribute("p", null, new Attribute(null, "class", "")));
    }

    @Test
    public void basic_addEnforcedAttributes_SimpleTextTest() {
        Safelist basicAttr = Safelist.basic().addEnforcedAttribute("img", "src", "test.jpg");
        assertTrue(basicAttr.isSafeAttribute("img", null, new Attribute(null, "src", "test.jpg")));
        assertFalse(basicAttr.isSafeAttribute("p", null, new Attribute(null, "class", "")));
    }

    @Test
    public void none_preserveRelativeLinks_SimpleTextTest() {
        Safelist nonePreserveImg = Safelist.none().preserveRelativeLinks(true);
        assertTrue(nonePreserveImg.isSafeAttribute("img", null, new Attribute(null, "src", "")));
        assertFalse(nonePreserveImg.isSafeAttribute("p", null, new Attribute(null, "class", "")));
    }

    @Test
    public void none_addProtocols_SimpleTextTest() {
        Safelist noneAddImgAttr = Safelist.none().addProtocols("img", "src", Arrays.asList("https://example.com"));
        assertTrue(noneAddImgAttr.isSafeAttribute("img", null, new Attribute(null, "src", "https://example.com")));
    }

    @Test
    public void basic_addTags_SimpleTextTest() {
        Safelist basicAddImg = Safelist.basic().addTags("img");
        assertTrue(basicAddImg.isSafeTag("img"));
        assertFalse(basicAddImg.isSafeTag("p"));
    }

    @Test
    public void basic_removeProtocols_SimpleTextTest() {
        Safelist basicRemoveImgAttr = Safelist.basic().removeProtocols("img", "src", Arrays.asList("https://example.com"));
        assertTrue(basicRemoveImgAttr.isSafeAttribute("img", null, new Attribute(null, "class", "")));
    }

}

